import Image from "next/image";
import { House, CalendarDays, Users, CreditCard, Clock3, CircleCheck, ClipboardCheck, BriefcaseBusiness, Banknote, ArrowUpRight, ChevronRight, MapPin, ShieldCheck, Star, Inbox } from "lucide-react";
import Link from "@/components/navigation-link";
import { adminDashboard } from "@/lib/admin-dashboard";
import type { AdminQuery } from "@/lib/admin-period";
import { requireAdmin } from "@/lib/auth";
import type { Locale } from "@/app/i18n/config";
import { formatNumber } from "@/app/i18n/format";
import { translated, type CommonDictionary } from "@/app/i18n/platform";
import type { AdminDictionary } from "@/app/i18n/admin";
import { AdminTrendChart } from "@/components/admin-trend-chart";
import { DashboardPeriod, DashboardTableFilters } from "@/components/admin-dashboard-controls";

export async function AdminDashboard({ locale, query }: { locale: Locale; query: AdminQuery }) {
  const user = await requireAdmin(locale);
  const [data, dictionary, common] = await Promise.all([adminDashboard(locale, query), translated<AdminDictionary>(locale, "admin"), translated<CommonDictionary>(locale, "common")]);
  const t = dictionary.dashboard, s = data.stats, range = data.range;
  const number = (value: number | string) => formatNumber(Number(value), locale, { maximumFractionDigits: 2 });
  const localTitle = (row: { title: string; titleKg: string | null; titleEn: string | null }) => (locale === "kg" ? row.titleKg : locale === "en" ? row.titleEn : null) || row.title;
  const date = (value: Date) => `${value.toISOString().slice(8, 10)}.${value.toISOString().slice(5, 7)}.${value.toISOString().slice(0, 4)}`;
  const periodParams = new URLSearchParams({ period: range.period, ...(range.period === "custom" ? { from: range.start, to: range.end } : {}) });
  const pageUrl = (page: number) => { const params = new URLSearchParams(periodParams); params.set("page", String(page)); if (data.q) params.set("q", data.q); if (data.status) params.set("status", data.status); return `/${locale}/admin?${params}`; };
  const mainStats = [
    { key: "bookings", label: t.bookings, value: s.bookings, icon: CalendarDays, scope: t.selectedPeriod, href: "bookings" },
    { key: "revenue", label: t.revenue, value: s.revenue, icon: Banknote, scope: t.selectedPeriod, href: "payments", money: true },
    { key: "cabins", label: t.cabins, value: s.cabins, icon: House, scope: t.allTime, href: "cabins" },
    { key: "users", label: t.users, value: s.users, icon: Users, scope: t.allTime, href: "users" },
  ];
  const secondaryStats = [
    { key: "published", label: t.published, value: s.published, icon: CircleCheck }, { key: "moderation", label: t.moderation, value: s.moderation, icon: ClipboardCheck },
    { key: "owners", label: t.owners, value: s.owners, icon: BriefcaseBusiness }, { key: "active", label: t.active, value: s.active, icon: CalendarDays },
    { key: "pending", label: t.pending, value: s.pending, icon: Clock3 }, { key: "paid", label: t.paid, value: s.paid, icon: CreditCard },
  ];
  const statusColors: Record<string, string> = { CONFIRMED: "#96b7a2", PENDING: "#DCC9A3", CANCELLED: "#bf8f84", COMPLETED: "#829cb3", REJECTED: "#807b88" };
  const statusParts = data.bookingGroups.map((row, i, rows) => ({ ...row, fraction: s.bookings ? row._count / s.bookings : 0, offset: rows.slice(0, i).reduce((sum, part) => sum + part._count, 0) / Math.max(s.bookings, 1) }));
  const quick = [{ href: "cabins", title: t.moderateCabins, icon: House }, { href: "bookings", title: t.manageBookings, icon: CalendarDays }, { href: "owners", title: t.verifyOwners, icon: ShieldCheck }, { href: "reviews", title: t.moderateReviews, icon: Star }];
  return <div className="admin-dashboard">
    <div className="admin-page-heading"><div><p className="admin-eyebrow">{t.welcome}, {user.firstName}</p><h1>{common.nav.dashboard}</h1><p>{t.intro}</p></div><div className="admin-live-label"><span />{t.live}</div></div>
    <div className="admin-dashboard-toolbar"><span className="admin-date-range"><CalendarDays size={15} />{range.start} — {range.end}<small>Asia/Bishkek</small></span><DashboardPeriod key={`${range.period}-${range.start}-${range.end}`} locale={locale} text={t} value={range.period} start={range.start} end={range.end} today={range.today} /></div>
    {range.invalid && <p className="admin-validation-error" role="alert">{t.invalidRange}</p>}
    <div className="admin-stat-grid">{mainStats.map(({ key, label, value, icon: Icon, scope, href, money }) => <Link key={key} href={`/${locale}/admin/${href}`} className={`admin-stat-card${money ? " admin-stat-accent" : ""}`}><div className="admin-stat-top"><span>{label}</span><Icon size={18} /></div><strong data-stat={key}>{number(value)}{money && <small> KGS</small>}</strong><div className="admin-stat-bottom"><span>{scope}</span><ArrowUpRight size={15} /></div></Link>)}</div>
    <div className="admin-secondary-stats">{secondaryStats.map(({ key, label, value, icon: Icon }) => <div key={key}><Icon size={17} /><span>{label}</span><strong data-stat={key}>{number(value)}</strong></div>)}</div>
    <div className="admin-chart-row"><AdminTrendChart locale={locale} text={t} series={data.series} /><section className="admin-panel admin-status-panel"><div className="admin-panel-heading"><div><h2>{t.statuses}</h2><p>{t.statusesDescription}</p></div></div><div className="admin-donut"><svg viewBox="0 0 160 160" role="img" aria-label={t.statuses}><circle cx="80" cy="80" r="62" fill="none" stroke="#24312b" strokeWidth="13" />{statusParts.map(row => <circle key={row.status} cx="80" cy="80" r="62" fill="none" stroke={statusColors[row.status]} strokeWidth="13" pathLength="100" strokeDasharray={`${row.fraction * 100} ${100 - row.fraction * 100}`} strokeDashoffset={-row.offset * 100} transform="rotate(-90 80 80)" />)}</svg><div><strong>{number(s.bookings)}</strong><span>{t.bookings}</span></div></div>{statusParts.length ? <ul className="admin-status-legend">{statusParts.map(row => <li key={row.status}><span className="admin-legend-dot" style={{ background: statusColors[row.status] }} /><span>{common.statuses[row.status]}</span><strong>{number(row._count)}</strong><small>{number(Math.round(row.fraction * 100))}%</small></li>)}</ul> : <p className="admin-muted-empty">{t.noPopular}</p>}</section></div>
    <div className="admin-insights-row"><section className="admin-panel"><div className="admin-panel-heading"><div><h2>{t.regions}</h2><p>{t.regionsDescription}</p></div><MapPin size={18} /></div>{data.regions.length ? <ol className="admin-region-list">{data.regions.map((row, index) => <li key={row.id}><span className="admin-rank">0{index + 1}</span><div><div><span>{(locale === "kg" ? row.nameKg : locale === "en" ? row.nameEn : null) || row.name}</span><strong>{number(row.value)}</strong></div><span className="admin-region-bar"><span style={{ width: `${row.value / data.regions[0].value * 100}%` }} /></span></div></li>)}</ol> : <div className="admin-small-empty"><MapPin size={25} /><p>{t.noPopular}</p></div>}</section><section className="admin-panel"><div className="admin-panel-heading"><div><h2>{t.popular}</h2><p>{t.popularDescription}</p></div><House size={18} /></div>{data.popular.length ? <ol className="admin-popular-list">{data.popular.map(({ count, cabin }, index) => <li key={cabin.id.toString()}><span className="admin-rank">0{index + 1}</span><span className="admin-cabin-thumbnail">{cabin.images[0]?.imageUrl.startsWith("/") && !cabin.images[0].imageUrl.startsWith("//") ? <Image src={cabin.images[0].imageUrl} alt="" width={48} height={48} sizes="48px" /> : <House size={22} />}</span><Link href={`/${locale}/admin/cabins?q=${encodeURIComponent(cabin.title)}`}>{localTitle(cabin)}</Link><strong>{number(count)}</strong></li>)}</ol> : <div className="admin-small-empty"><House size={25} /><p>{t.noPopular}</p></div>}</section><section className="admin-panel admin-quick-panel"><div className="admin-panel-heading"><div><h2>{t.quick}</h2><p>{t.quickDescription}</p></div></div><div className="admin-quick-links">{quick.map(({ href, title, icon: Icon }) => <Link key={href} href={`/${locale}/admin/${href}`}><span><Icon size={17} /></span>{title}<ChevronRight size={16} /></Link>)}</div></section></div>
    <section className="admin-panel admin-bookings-panel"><div className="admin-panel-heading"><div><h2>{t.recent}</h2><p>{t.recentDescription}</p></div><Link className="admin-text-link" href={`/${locale}/admin/bookings`}>{t.allBookings}<ArrowUpRight size={15} /></Link></div><DashboardTableFilters key={`${data.q}-${data.status}-${range.start}-${range.end}`} locale={locale} text={t} common={common} q={data.q} status={data.status} period={range.period} start={range.start} end={range.end} />
      {data.recent.length ? <><div className="admin-table-scroll" tabIndex={0} role="region" aria-label={t.recent}><table className="admin-bookings-table"><caption className="sr-only">{t.recent}</caption><thead><tr>{[t.booking, t.guest, t.cabin, t.stay, t.amount, t.status].map(label => <th scope="col" key={label}>{label}</th>)}</tr></thead><tbody>{data.recent.map(row => <tr key={row.id.toString()}><td><Link href={`/${locale}/bookings/${row.id}`}>{row.bookingNumber}<ArrowUpRight size={13} /></Link></td><td>{row.guestName}</td><td>{localTitle(row.cabin)}</td><td className="admin-stay-cell">{date(row.checkIn)} — {date(row.checkOut)}</td><td className="admin-amount-cell">{number(row.totalAmount.toString())}<small> KGS</small></td><td><span className="admin-status-badge" data-status={row.status}><i />{common.statuses[row.status]}</span></td></tr>)}</tbody></table></div></> : <div className="admin-table-empty"><Inbox size={29} /><h3>{t.empty}</h3><p>{t.emptyDescription}</p>{(data.q || data.status) && <Link className="admin-button" href={`/${locale}/admin?${periodParams}`}>{t.reset}</Link>}</div>}
      <div className="admin-table-footer"><span>{number(data.recentCount)} {t.records}</span><nav aria-label={t.page}>{data.page > 1 && <Link className="admin-button" href={pageUrl(data.page - 1)} scroll={false}>{t.previous}</Link>}<span>{t.page} {number(data.page)} {t.of} {number(Math.max(1, Math.ceil(data.recentCount / data.take)))}</span>{data.page * data.take < data.recentCount && <Link className="admin-button" href={pageUrl(data.page + 1)} scroll={false}>{t.next}</Link>}</nav></div>
    </section>
    <aside className="admin-provider-notice"><CreditCard size={21} /><div><strong>{data.providerConfigured ? t.providerConfigured : t.providerUnavailable}</strong><p>{data.providerConfigured ? t.providerConfiguredDescription : t.providerUnavailableDescription}</p></div><Link href={`/${locale}/admin/payments`} aria-label={common.nav.payments}><ArrowUpRight size={18} /></Link></aside><p className="admin-data-note"><ShieldCheck size={14} />{t.source}</p>
  </div>;
}
